import{_ as d,o as a,c as e,ag as o}from"./chunks/framework.C9sp7nFj.js";const h=JSON.parse('{"title":"APOS","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/2. 位置数据类型/APOS.md","filePath":"2. 变量数据类型/2. 位置数据类型/APOS.md","lastUpdated":1778862643000}'),r={name:"2. 变量数据类型/2. 位置数据类型/APOS.md"};function c(s,t,n,l,p,_){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="apos" tabindex="-1">APOS <a class="header-anchor" href="#apos" aria-label="Permalink to &quot;APOS&quot;">​</a></h1><p>关节位置类型 - 这是基于<strong>关节空间</strong>的数据类型。</p><p>存储关节空间下各个轴的坐标值。该变量可支持用户自主创建以及修改，也可在示教程序中进行赋值运算等操作。同时该变量支持在全局，工程，程序三大变量作用域中创建，删除，修改，复制，粘贴等操作（其中复制、粘贴操作不能跨域和跨工程）。</p><p><strong>含义：</strong> 存储机器人各轴在关节空间中的坐标值（角度或位移）。</p><p><strong>构成：</strong> 包含 <code>a1</code> 到 <code>a16</code>。对于常见的六轴机器人，有效数据通常为 <code>a1~a6</code>。</p><p><strong>特点：</strong> 直接对应电机轴的旋转位置，不涉及坐标系转换，是机器人最基础的位置表达。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>a1</code></td><td>real</td><td>关节 1 号轴的坐标。</td><td>—</td></tr><tr><td><code>a2</code></td><td>real</td><td>关节 2 号轴的坐标。</td><td>—</td></tr><tr><td><code>a3</code></td><td>real</td><td>关节 3 号轴的坐标。</td><td>—</td></tr><tr><td><code>a16</code></td><td>real</td><td>关节 16 号轴的坐标。</td><td>机器人有几个轴就会显示几个轴的参数。如通用六轴机器人显示 a1~a6,scara 机器人显示为 a1~a4.</td></tr><tr><td><code>note</code></td><td>string</td><td>变量注释。</td><td>—</td></tr></tbody></table><ul><li>...：参数 a4~a15 的属性跟上述一样，都是 real 型变量，依次表示关节 4~关节 15 号轴的坐标值。。</li></ul>',8)])])}const P=d(r,[["render",c]]);export{h as __pageData,P as default};
